// dyna:decimal against CPython's decimal module (libmpdec), an independent
// implementation of the General Decimal Arithmetic specification
// (tests/corpus/ref/decimal_vectors.js, generated by
// tools/gen_decimal_ref_vectors.py). Exact operations must match digit for
// digit; div/pow at a precision must round exactly as the named mode says;
// sqrt/exp/ln/log10 are promised correctly rounded half-even, so they must
// match libmpdec's correctly rounded answer to the last digit too.
import { Decimal } from "dyna:decimal";
import { ROWS } from "../corpus/ref/decimal_vectors.js";

let n = 0, fails = 0;
function fail(m) { fails++; print("FAIL: " + m); }

const D = (s) => new Decimal(s);
const OPS = {
    add: ([a, b]) => String(D(a).add(b)),
    sub: ([a, b]) => String(D(a).sub(b)),
    mul: ([a, b]) => String(D(a).mul(b)),
    cmp: ([a, b]) => D(a).cmp(b),
    equals: ([a, b]) => D(a).equals(b),
    mod: ([a, b]) => String(D(a).mod(b)),
    divmod: ([a, b]) => D(a).divmod(b).map(String),
    div: ([a, b, p, mode]) => String(D(a).div(b, { precision: p, rounding: mode })),
    pow: ([a, k, p, mode]) => String(D(a).pow(k, { precision: p, rounding: mode })),
    sqrt: ([a, p]) => String(D(a).sqrt({ precision: p })),
    exp: ([a, p]) => String(D(a).exp({ precision: p })),
    ln: ([a, p]) => String(D(a).ln({ precision: p })),
    log10: ([a, p]) => String(D(a).log10({ precision: p })),
    round: ([a, dp, mode]) => String(D(a).round(dp, mode)),
    toFixed: ([a, dp, mode]) => D(a).toFixed(dp, mode),
    floor: ([a]) => String(D(a).floor()),
    ceil: ([a]) => String(D(a).ceil()),
    trunc: ([a]) => String(D(a).trunc()),
    digits: ([a]) => D(a).digits(),
    toNumber: ([a]) => D(a).toNumber(),
    fromNumber: ([v]) => String(new Decimal(v)),
};

const byOp = new Map();
for (const [op, args, want] of ROWS) {
    const fn = OPS[op];
    n++;
    if (!fn) { fail("the vectors test '" + op + "' and this suite has no mapping for it"); continue; }
    byOp.set(op, (byOp.get(op) || 0) + 1);
    let got;
    try { got = fn(args); } catch (e) { fail(op + "(" + JSON.stringify(args) + ") threw " + e.message); continue; }
    const same = Array.isArray(want) ? JSON.stringify(got) === JSON.stringify(want) : Object.is(got, want);
    if (!same) fail(op + "(" + JSON.stringify(args).slice(1, -1) + ") = " + JSON.stringify(got) + ", want " + JSON.stringify(want));
}
for (const op of Object.keys(OPS)) if (!byOp.has(op)) { n++; fail("no vector exercises '" + op + "' -- regenerate the vectors"); }

print("test_decimal_ref: " + n + " checks (" + [...byOp].map(([k, v]) => k + " " + v).join(", ") + "), " + fails + " failures");
if (fails) throw new Error(fails + " failures");
